import fs from 'node:fs';import path from 'node:path';import {spawn} from 'node:child_process';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const stage='F:/VisibleMedicine/staging/20261023-fda-review-source',root=stage+'/atlas',phase=process.argv[2];
const jobs={legacy:['scripts/validate-specimen-review.mjs'],index:['--test','scripts/test-clinical-review-index.mjs','scripts/test-clinical-review-page.mjs','scripts/test-clinical-review-queue.mjs','scripts/test-clinical-review-results.mjs','scripts/test-review-entry-track.mjs'],build:[path.join(path.dirname(process.execPath),'node_modules/npm/bin/npm-cli.js'),'run','build']};
assert(jobs[phase]);const out=stage+'/checks/'+phase;assert(!fs.existsSync(out));fs.mkdirSync(out,{recursive:true});const stdout=fs.createWriteStream(out+'/stdout.log',{flags:'wx'}),stderr=fs.createWriteStream(out+'/stderr.log',{flags:'wx'});
const child=spawn(process.execPath,jobs[phase],{cwd:root,windowsHide:true,stdio:['ignore','pipe','pipe'],env:{...process.env,NODE_OPTIONS:'--max-old-space-size=768',RAYON_NUM_THREADS:'1',GOMAXPROCS:'2',GIT_NO_REPLACE_OBJECTS:'1'}});child.stdout.pipe(stdout);child.stderr.pipe(stderr);console.log(JSON.stringify({phase,pid:child.pid,driver:process.pid}));
